{"path": "/tmp/sv-d0e63447956d42769b24ad5ccba0c944/RecipeCommunity/Services/RecipeService.cs", "file_text": "using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Ingredients = "Pizza dough\nMozzarella cheese\nFresh basil\nTomato sauce\nOlive oil", Steps = "1. Preheat oven to 475°F.\n2. Roll out dough on floured surface.\n3. Spread tomato sauce evenly.\n4. Add mozzarella slices.\n5. Bake for 10-12 minutes.\n6. Top with fresh basil and drizzle olive oil.", AverageRating = 4.5, RatingCount = 12 },
        new Recipe { Id = 2, Title = "Spaghetti Carbonara", Category = "Italian", Ingredients = "Spaghetti\nPancetta\nEggs\nParmesan cheese\nBlack pepper", Steps = "1. Cook spaghetti al dente.\n2. Fry pancetta until crispy.\n3. Whisk eggs with grated Parmesan.\n4. Toss hot pasta with pancetta.\n5. Remove from heat, stir in egg mixture.\n6. Season with black pepper.", AverageRating = 4.8, RatingCount = 20 },
        new Recipe { Id = 3, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken breast\nYogurt\nTikka masala paste\nCanned tomatoes\nHeavy cream\nRice", Steps = "1. Marinate chicken in yogurt and spices.\n2. Grill or pan-fry chicken pieces.\n3. Simmer tomatoes with tikka paste.\n4. Add cream and cooked chicken.\n5. Cook for 15 minutes.\n6. Serve over basmati rice.", AverageRating = 4.6, RatingCount = 15 },
        new Recipe { Id = 4, Title = "Vegetable Pad Thai", Category = "Asian", Ingredients = "Rice noodles\nTofu\nBean sprouts\nPeanuts\nLime\nPad Thai sauce\nGreen onions", Steps = "1. Soak rice noodles in warm water.\n2. Press and cube tofu, then pan-fry.\n3. Stir-fry vegetables briefly.\n4. Add noodles and Pad Thai sauce.\n5. Toss with bean sprouts and peanuts.\n6. Serve with lime wedges.", AverageRating = 4.3, RatingCount = 8 },
        new Recipe { Id = 5, Title = "Beef Tacos", Category = "Mexican", Ingredients = "Ground beef\nTaco shells\nLettuce\nTomato\nCheddar cheese\nSour cream\nTaco seasoning", Steps = "1. Brown ground beef with taco seasoning.\n2. Warm taco shells in oven.\n3. Dice lettuce and tomatoes.\n4. Shred cheese.\n5. Assemble tacos with toppings.\n6. Serve with sour cream.", AverageRating = 4.2, RatingCount = 10 },
        new Recipe { Id = 6, Title = "Chocolate Lava Cake", Category = "Desserts", Ingredients = "Dark chocolate\nButter\nEggs\nSugar\nFlour\nVanilla extract", Steps = "1. Melt chocolate and butter together.\n2. Whisk eggs and sugar until fluffy.\n3. Fold in chocolate mixture.\n4. Add flour and vanilla.\n5. Pour into greased ramekins.\n6. Bake at 425°F for 12 minutes.\n7. Invert onto plates immediately.", AverageRating = 4.9, RatingCount = 25 },
        new Recipe { Id = 7, Title = "Guacamole", Category = "Mexican", Ingredients = "Avocados\nLime juice\nCilantro\nRed onion\nTomato\nJalapeño\nSalt", Steps = "1. Halve and pit avocados.\n2. Mash to desired consistency.\n3. Dice onion, tomato, and jalapeño.\n4. Mix all ingredients together.\n5. Add lime juice and salt.\n6. Serve with tortilla chips.", AverageRating = 4.4, RatingCount = 18 },
        new Recipe { Id = 8, Title = "Miso Ramen", Category = "Asian", Ingredients = "Ramen noodles\nMiso paste\nChicken broth\nSoft-boiled egg\nGreen onions\nNori\nChashu pork", Steps = "1. Simmer broth with miso paste.\n2. Cook ramen noodles separately.\n3. Prepare soft-boiled eggs (6 min).\n4. Slice chashu pork.\n5. Assemble bowl with noodles and broth.\n6. Top with egg, pork, nori, and green onions.", AverageRating = 4.7, RatingCount = 14 },
    };

    private int _nextId = 9;

    public List<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();
    }

    public List<Recipe> GetRecipesByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetRecipeById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is not null && stars >= 1 && stars <= 5)
        {
            var totalStars = recipe.AverageRating * recipe.RatingCount;
            recipe.RatingCount++;
            recipe.AverageRating = Math.Round((totalStars + stars) / recipe.RatingCount, 1);
        }
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }
}
"}

