@rendermode InteractiveServer

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= _selectedRating ? "filled" : "")"
              @onclick="() => Rate(star)"
              role="button"
              title="Rate @star stars">
            @(star <= _selectedRating ? "★" : "☆")
        </span>
    }
    <span class="rating-info ms-2">
        (@Rating.ToString("0.0") avg, @RatingCount ratings)
    </span>
</div>

@if (_submitted)
{
    <div class="alert alert-success mt-2 py-1 px-2 d-inline-block">
        Thanks for rating!
    </div>
}

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double Rating { get; set; }
    [Parameter] public int RatingCount { get; set; }
    [Parameter] public EventCallback<int> OnRated { get; set; }

    private int _selectedRating;
    private bool _submitted;

    private async Task Rate(int stars)
    {
        _selectedRating = stars;
        _submitted = true;
        await OnRated.InvokeAsync(stars);
    }
}

.star-rating .star {
    font-size: 1.5rem;
    cursor: pointer;
    color: #ccc;
    transition: color 0.2s;
}

.star-rating .star:hover,
.star-rating .star.filled {
    color: #f5a623;
}

.star-rating .rating-info {
    font-size: 0.9rem;
    color: #666;
}

