@page "/category/{CategoryName}"
@using RecipeCommunity.Services
@using RecipeCommunity.Models

<PageTitle>@CategoryName Recipes</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">@CategoryName</li>
    </ol>
</nav>

<h1>@CategoryName Recipes</h1>

@if (_recipes.Any())
{
    <div class="row">
        @foreach (var recipe in _recipes)
        {
            <div class="col-md-6 mb-3">
                <div class="card shadow-sm">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="text-muted mb-1">
                            ★ @recipe.AverageRating.ToString("0.0") (@recipe.RatingCount ratings)
                        </p>
                        <a href="/recipe/@recipe.Id" class="btn btn-primary btn-sm">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}
else
{
    <div class="alert alert-info">No recipes found in this category.</div>
}

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;
    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private List<Recipe> _recipes = new();

    protected override void OnParametersSet()
    {
        _recipes = RecipeService.GetRecipesByCategory(CategoryName);
    }
}

@page "/recipe/{RecipeId:int}"
@using RecipeCommunity.Services
@using RecipeCommunity.Models
@using RecipeCommunity.Components.Shared

<PageTitle>@(_recipe?.Title ?? "Recipe")</PageTitle>

@if (_recipe is null)
{
    <div class="alert alert-warning">Recipe not found.</div>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="/category/@_recipe.Category">@_recipe.Category</a></li>
            <li class="breadcrumb-item active">@_recipe.Title</li>
        </ol>
    </nav>

    <h1>@_recipe.Title</h1>
    <span class="badge bg-secondary mb-3">@_recipe.Category</span>

    <div class="mb-4">
        <StarRating RecipeId="@_recipe.Id"
                    Rating="@_recipe.AverageRating"
                    RatingCount="@_recipe.RatingCount"
                    OnRated="HandleRating" />
    </div>

    <div class="row">
        <div class="col-md-4">
            <div class="card mb-3">
                <div class="card-header"><strong>Ingredients</strong></div>
                <div class="card-body">
                    <ul class="mb-0">
                        @foreach (var ingredient in _recipe.Ingredients.Split('\n'))
                        {
                            <li>@ingredient</li>
                        }
                    </ul>
                </div>
            </div>
        </div>
        <div class="col-md-8">
            <div class="card">
                <div class="card-header"><strong>Steps</strong></div>
                <div class="card-body">
                    @foreach (var step in _recipe.Steps.Split('\n'))
                    {
                        <p class="mb-1">@step</p>
                    }
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter] public int RecipeId { get; set; }
    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private Recipe? _recipe;

    protected override void OnParametersSet()
    {
        _recipe = RecipeService.GetRecipeById(RecipeId);
    }

    private void HandleRating(int stars)
    {
        RecipeService.AddRating(RecipeId, stars);
        _recipe = RecipeService.GetRecipeById(RecipeId);
    }
}

@page "/submit"
@using RecipeCommunity.Services
@using RecipeCommunity.Models
@rendermode InteractiveServer

<PageTitle>Submit a Recipe</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">Submit Recipe</li>
    </ol>
</nav>

<h1>Submit a Recipe</h1>
<p class="text-muted">Share your favorite recipe with the community!</p>

@if (_submitted)
{
    <div class="alert alert-success">
        <h4>Recipe Submitted!</h4>
        <p>Your recipe "<strong>@_title</strong>" has been added to the @_category category.</p>
        <a href="/category/@_category" class="btn btn-primary">View Category</a>
        <button class="btn btn-outline-secondary ms-2" @onclick="Reset">Submit Another</button>
    </div>
}
else
{
    <EditForm Model="@this" OnValidSubmit="HandleSubmit" FormName="recipeForm">
        <div class="row">
            <div class="col-md-8">
                <div class="mb-3">
                    <label for="title" class="form-label">Recipe Title</label>
                    <InputText id="title" @bind-Value="_title" class="form-control" required />
                </div>

                <div class="mb-3">
                    <label for="category" class="form-label">Category</label>
                    <InputSelect id="category" @bind-Value="_category" class="form-select">
                        <option value="">-- Select a category --</option>
                        <option value="Italian">Italian</option>
                        <option value="Indian">Indian</option>
                        <option value="Asian">Asian</option>
                        <option value="Mexican">Mexican</option>
                        <option value="Desserts">Desserts</option>
                    </InputSelect>
                </div>

                <div class="mb-3">
                    <label for="ingredients" class="form-label">Ingredients (one per line)</label>
                    <InputTextArea id="ingredients" @bind-Value="_ingredients" class="form-control" rows="6" />
                </div>

                <div class="mb-3">
                    <label for="steps" class="form-label">Steps (one per line)</label>
                    <InputTextArea id="steps" @bind-Value="_steps" class="form-control" rows="8" />
                </div>

                <button type="submit" class="btn btn-success"
                        disabled="@(string.IsNullOrWhiteSpace(_title) || string.IsNullOrWhiteSpace(_category))">
                    Submit Recipe
                </button>
            </div>
        </div>
    </EditForm>
}

@code {
    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private string _title = string.Empty;
    private string _category = string.Empty;
    private string _ingredients = string.Empty;
    private string _steps = string.Empty;
    private bool _submitted;

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(_title) || string.IsNullOrWhiteSpace(_category))
            return;

        var recipe = new Recipe
        {
            Title = _title,
            Category = _category,
            Ingredients = _ingredients,
            Steps = _steps
        };

        RecipeService.AddRecipe(recipe);
        _submitted = true;
    }

    private void Reset()
    {
        _title = string.Empty;
        _category = string.Empty;
        _ingredients = string.Empty;
        _steps = string.Empty;
        _submitted = false;
    }
}

